// Ranged dragonhide. tiers is where that color shows up, and the weight is
// how it shares the slot with the other colors there. Strength stays on tier:
// green with adamant, blue with rune, black with dragon.
function hidePiece(id, name, slot, tier, tiers, osrsId, hide, req) {
  const row = { id, name, slot, tier, tiers, baseId: id, osrsId, hide, gearStyle: 'ranged', plainName: true };
  if (req) row.req = req;
  return row;
}

