// Robes and a few other sets people actually wear. Power stays on `tier`.
// `tiers` is which crates they turn up in. Magic pieces ask for Magic.
// cloth and shape are how the portrait paints them.
function clothPiece(id, name, slot, tier, tiers, osrsId, extra) {
  return Object.assign({
    id,
    name,
    slot,
    tier,
    tiers,
    osrsId,
    baseId: id,
    plainName: true,
  }, extra);
}

