const SLOTS = ['weapon', 'shield', 'head', 'body', 'legs', 'boots', 'gloves', 'cape', 'neck', 'ring', 'ammo'];

// Real pieces for the top of the table. Dragon stays mostly dragon metal, with a
// few of these mixed in. Barrows and raid drops come from this list, so a find
// is a whip or a blood moon chestplate rather than "barrows platebody".
// weight is how often it shows up inside its tier. rare marks the crate sheet.
function namedGear(id, name, slot, tier, baseId, osrsId, extra) {
  const row = extra || {};
  const item = {
    id,
    name,
    slot,
    tier,
    baseId,
    osrsId,
    style: row.style || null,
    plainName: true,
  };
  if (row.gearStyle) item.gearStyle = row.gearStyle;
  if (row.weight) item.weight = row.weight;
  if (row.rare) item.rare = true;
  if (row.req) item.req = row.req;
  return item;
}

