// Megarares. Only a megarare chest rolls these, plus the one raid that drops a
// piece as its own unique. Each sits on raid metal, but `power` replaces the
// tier sheet: those numbers are what the piece adds to a fight. Inside a slot
// no two share a job, so the slot is a choice rather than a ladder.
function megaPiece(id, name, slot, baseId, osrsId, power, extra) {
  return Object.assign({
    id,
    name,
    slot,
    tier: 'raid',
    baseId,
    osrsId,
    plainName: true,
    mega: true,
    power,
  }, extra);
}

