function catalogRows(list, ids) {
  return ids.map((id) => {
    const row = list.find((item) => item.id === id);
    if (!row) throw new Error('Missing crate piece ' + id);
    return row;
  });
}

// A real bow or staff, with its own name, so a style crate does not roll "adamant shortbow".
function styleWeapon(id, name, tier, baseId, style, osrsId, req) {
  return {
    id,
    name,
    slot: 'weapon',
    tier,
    baseId,
    style,
    osrsId,
    plainName: true,
    gearStyle: style,
    req,
  };
}

function styleAmmo(id, name, tier, osrsId, req) {
  return {
    id,
    name,
    slot: 'ammo',
    tier,
    baseId: 'ammo',
    osrsId,
    plainName: true,
    gearStyle: 'ranged',
    req,
  };
}

